00060 // ------------------------------------------------------------------------------------------------
00062 template <typename TReal>
00063 AI_FORCE_INLINE
00064 aiQuaterniont<TReal> operator * (const aiMatrix4x4t<TReal>& pMatrix, const aiQuaterniont<TReal>& pQuaternion) {
00065     aiQuaterniont<TReal> res;
00066     res.x = pMatrix.a1 * pQuaternion.x + pMatrix.a2 * pQuaternion.y + pMatrix.a3 * pQuaternion.z + pMatrix.a4 * pQuaternion.w;
00067     res.y = pMatrix.b1 * pQuaternion.x + pMatrix.b2 * pQuaternion.y + pMatrix.b3 * pQuaternion.z + pMatrix.b4 * pQuaternion.w;
00068     res.z = pMatrix.c1 * pQuaternion.x + pMatrix.c2 * pQuaternion.y + pMatrix.c3 * pQuaternion.z + pMatrix.c4 * pQuaternion.w;
00069     res.w = pMatrix.d1 * pQuaternion.x + pMatrix.d2 * pQuaternion.y + pMatrix.d3 * pQuaternion.z + pMatrix.d4 * pQuaternion.w;
00070     return res;
00071 }
00072 // ---------------------------------------------------------------------------
00073 template<typename TReal>
00074 bool aiQuaterniont<TReal>::operator== (const aiQuaterniont& o) const
00075 {
00076     return x == o.x && y == o.y && z == o.z && w == o.w;
00077 }
00078 
00079 // ---------------------------------------------------------------------------
00080 template<typename TReal>
00081 bool aiQuaterniont<TReal>::operator!= (const aiQuaterniont& o) const
00082 {
00083     return !(*this == o);
00084 }
00085 
00086 // ------------------------------------------------------------------------------------------------
00087 template <typename TReal>
00088 AI_FORCE_INLINE
00089 aiQuaterniont<TReal>& aiQuaterniont<TReal>::operator *= (const aiMatrix4x4t<TReal>& mat){
00090     return (*this = mat * (*this));
00091 }
00092 // ------------------------------------------------------------------------------------------------
00093 
00094 // ---------------------------------------------------------------------------
00095 template<typename TReal>
00096 inline bool aiQuaterniont<TReal>::Equal(const aiQuaterniont& o, TReal epsilon) const {
00097     return
00098         std::abs(x - o.x) <= epsilon &&
00099         std::abs(y - o.y) <= epsilon &&
00100         std::abs(z - o.z) <= epsilon &&
00101         std::abs(w - o.w) <= epsilon;
00102 }
00103 
00104 // ---------------------------------------------------------------------------
00105 // Constructs a quaternion from a rotation matrix
00106 template<typename TReal>
00107 inline aiQuaterniont<TReal>::aiQuaterniont( const aiMatrix3x3t<TReal> &pRotMatrix)
00108 {
00109     TReal t = pRotMatrix.a1 + pRotMatrix.b2 + pRotMatrix.c3;
00110 
00111     // large enough
00112     if( t > static_cast<TReal>(0))
00113     {
00114         TReal s = std::sqrt(1 + t) * static_cast<TReal>(2.0);
00115         x = (pRotMatrix.c2 - pRotMatrix.b3) / s;
00116         y = (pRotMatrix.a3 - pRotMatrix.c1) / s;
00117         z = (pRotMatrix.b1 - pRotMatrix.a2) / s;
00118         w = static_cast<TReal>(0.25) * s;
00119     } // else we have to check several cases
00120     else if( pRotMatrix.a1 > pRotMatrix.b2 && pRotMatrix.a1 > pRotMatrix.c3 )
00121     {
00122         // Column 0:
00123         TReal s = std::sqrt( static_cast<TReal>(1.0) + pRotMatrix.a1 - pRotMatrix.b2 - pRotMatrix.c3) * static_cast<TReal>(2.0);
00124         x = static_cast<TReal>(0.25) * s;
00125         y = (pRotMatrix.b1 + pRotMatrix.a2) / s;
00126         z = (pRotMatrix.a3 + pRotMatrix.c1) / s;
00127         w = (pRotMatrix.c2 - pRotMatrix.b3) / s;
00128     }
00129     else if( pRotMatrix.b2 > pRotMatrix.c3)
00130     {
00131         // Column 1:
00132         TReal s = std::sqrt( static_cast<TReal>(1.0) + pRotMatrix.b2 - pRotMatrix.a1 - pRotMatrix.c3) * static_cast<TReal>(2.0);
00133         x = (pRotMatrix.b1 + pRotMatrix.a2) / s;
00134         y = static_cast<TReal>(0.25) * s;
00135         z = (pRotMatrix.c2 + pRotMatrix.b3) / s;
00136         w = (pRotMatrix.a3 - pRotMatrix.c1) / s;
00137     } else
00138     {
00139         // Column 2:
00140         TReal s = std::sqrt( static_cast<TReal>(1.0) + pRotMatrix.c3 - pRotMatrix.a1 - pRotMatrix.b2) * static_cast<TReal>(2.0);
00141         x = (pRotMatrix.a3 + pRotMatrix.c1) / s;
00142         y = (pRotMatrix.c2 + pRotMatrix.b3) / s;
00143         z = static_cast<TReal>(0.25) * s;
00144         w = (pRotMatrix.b1 - pRotMatrix.a2) / s;
00145     }
00146 }
00147 
00148 // ---------------------------------------------------------------------------
00149 // Construction from euler angles
00150 template<typename TReal>
00151 inline aiQuaterniont<TReal>::aiQuaterniont( TReal fPitch, TReal fYaw, TReal fRoll )
00152 {
00153     const TReal fSinPitch(std::sin(fPitch*static_cast<TReal>(0.5)));
00154     const TReal fCosPitch(std::cos(fPitch*static_cast<TReal>(0.5)));
00155     const TReal fSinYaw(std::sin(fYaw*static_cast<TReal>(0.5)));
00156     const TReal fCosYaw(std::cos(fYaw*static_cast<TReal>(0.5)));
00157     const TReal fSinRoll(std::sin(fRoll*static_cast<TReal>(0.5)));
00158     const TReal fCosRoll(std::cos(fRoll*static_cast<TReal>(0.5)));
00159     const TReal fCosPitchCosYaw(fCosPitch*fCosYaw);
00160     const TReal fSinPitchSinYaw(fSinPitch*fSinYaw);
00161     x = fSinRoll * fCosPitchCosYaw     - fCosRoll * fSinPitchSinYaw;
00162     y = fCosRoll * fSinPitch * fCosYaw + fSinRoll * fCosPitch * fSinYaw;
00163     z = fCosRoll * fCosPitch * fSinYaw - fSinRoll * fSinPitch * fCosYaw;
00164     w = fCosRoll * fCosPitchCosYaw     + fSinRoll * fSinPitchSinYaw;
00165 }
00166 
00167 // ---------------------------------------------------------------------------
00168 // Returns a matrix representation of the quaternion
00169 template<typename TReal>
00170 inline aiMatrix3x3t<TReal> aiQuaterniont<TReal>::GetMatrix() const
00171 {
00172     aiMatrix3x3t<TReal> resMatrix;
00173     resMatrix.a1 = static_cast<TReal>(1.0) - static_cast<TReal>(2.0) * (y * y + z * z);
00174     resMatrix.a2 = static_cast<TReal>(2.0) * (x * y - z * w);
00175     resMatrix.a3 = static_cast<TReal>(2.0) * (x * z + y * w);
00176     resMatrix.b1 = static_cast<TReal>(2.0) * (x * y + z * w);
00177     resMatrix.b2 = static_cast<TReal>(1.0) - static_cast<TReal>(2.0) * (x * x + z * z);
00178     resMatrix.b3 = static_cast<TReal>(2.0) * (y * z - x * w);
00179     resMatrix.c1 = static_cast<TReal>(2.0) * (x * z - y * w);
00180     resMatrix.c2 = static_cast<TReal>(2.0) * (y * z + x * w);
00181     resMatrix.c3 = static_cast<TReal>(1.0) - static_cast<TReal>(2.0) * (x * x + y * y);
00182 
00183     return resMatrix;
00184 }
00185 
00186 // ---------------------------------------------------------------------------
00187 // Construction from an axis-angle pair
00188 template<typename TReal>
00189 inline aiQuaterniont<TReal>::aiQuaterniont( aiVector3t<TReal> axis, TReal angle)
00190 {
00191     axis.Normalize();
00192 
00193     const TReal sin_a = std::sin( angle / 2 );
00194     const TReal cos_a = std::cos( angle / 2 );
00195     x    = axis.x * sin_a;
00196     y    = axis.y * sin_a;
00197     z    = axis.z * sin_a;
00198     w    = cos_a;
00199 }
00200 // ---------------------------------------------------------------------------
00201 // Construction from am existing, normalized quaternion
00202 template<typename TReal>
00203 inline aiQuaterniont<TReal>::aiQuaterniont( aiVector3t<TReal> normalized)
00204 {
00205     x = normalized.x;
00206     y = normalized.y;
00207     z = normalized.z;
00208 
00209     const TReal t = static_cast<TReal>(1.0) - (x*x) - (y*y) - (z*z);
00210 
00211     if (t < static_cast<TReal>(0.0)) {
00212         w = static_cast<TReal>(0.0);
00213     }
00214     else w = std::sqrt (t);
00215 }
00216 
00217 // ---------------------------------------------------------------------------
00218 // Performs a spherical interpolation between two quaternions
00219 // Implementation adopted from the gmtl project. All others I found on the net fail in some cases.
00220 // Congrats, gmtl!
00221 template<typename TReal>
00222 inline void aiQuaterniont<TReal>::Interpolate( aiQuaterniont& pOut, const aiQuaterniont& pStart, const aiQuaterniont& pEnd, TReal pFactor)
00223 {
00224     // calc cosine theta
00225     TReal cosom = pStart.x * pEnd.x + pStart.y * pEnd.y + pStart.z * pEnd.z + pStart.w * pEnd.w;
00226 
00227     // adjust signs (if necessary)
00228     aiQuaterniont end = pEnd;
00229     if( cosom < static_cast<TReal>(0.0))
00230     {
00231         cosom = -cosom;
00232         end.x = -end.x;   // Reverse all signs
00233         end.y = -end.y;
00234         end.z = -end.z;
00235         end.w = -end.w;
00236     }
00237 
00238     // Calculate coefficients
00239     TReal sclp, sclq;
00240     if( (static_cast<TReal>(1.0) - cosom) > static_cast<TReal>(0.0001)) // 0.0001 -> some epsillon
00241     {
00242         // Standard case (slerp)
00243         TReal omega, sinom;
00244         omega = std::acos( cosom); // extract theta from dot product's cos theta
00245         sinom = std::sin( omega);
00246         sclp  = std::sin( (static_cast<TReal>(1.0) - pFactor) * omega) / sinom;
00247         sclq  = std::sin( pFactor * omega) / sinom;
00248     } else
00249     {
00250         // Very close, do linear interp (because it's faster)
00251         sclp = static_cast<TReal>(1.0) - pFactor;
00252         sclq = pFactor;
00253     }
00254 
00255     pOut.x = sclp * pStart.x + sclq * end.x;
00256     pOut.y = sclp * pStart.y + sclq * end.y;
00257     pOut.z = sclp * pStart.z + sclq * end.z;
00258     pOut.w = sclp * pStart.w + sclq * end.w;
00259 }
00260 
00261 // ---------------------------------------------------------------------------
00262 template<typename TReal>
00263 inline aiQuaterniont<TReal>& aiQuaterniont<TReal>::Normalize()
00264 {
00265     // compute the magnitude and divide through it
00266     const TReal mag = std::sqrt(x*x + y*y + z*z + w*w);
00267     if (mag)
00268     {
00269         const TReal invMag = static_cast<TReal>(1.0)/mag;
00270         x *= invMag;
00271         y *= invMag;
00272         z *= invMag;
00273         w *= invMag;
00274     }
00275     return *this;
00276 }
00277 
00278 // ---------------------------------------------------------------------------
00279 template<typename TReal>
00280 inline aiQuaterniont<TReal> aiQuaterniont<TReal>::operator* (const aiQuaterniont& t) const
00281 {
00282     return aiQuaterniont(w*t.w - x*t.x - y*t.y - z*t.z,
00283         w*t.x + x*t.w + y*t.z - z*t.y,
00284         w*t.y + y*t.w + z*t.x - x*t.z,
00285         w*t.z + z*t.w + x*t.y - y*t.x);
00286 }
00287 
00288 // ---------------------------------------------------------------------------
00289 template<typename TReal>
00290 inline aiQuaterniont<TReal>& aiQuaterniont<TReal>::Conjugate ()
00291 {
00292     x = -x;
00293     y = -y;
00294     z = -z;
00295     return *this;
00296 }
00297 
00298 // ---------------------------------------------------------------------------
00299 template<typename TReal>
00300 inline aiVector3t<TReal> aiQuaterniont<TReal>::Rotate (const aiVector3t<TReal>& v) const
00301 {
00302     aiQuaterniont q2(0.f,v.x,v.y,v.z), q = *this, qinv = q;
00303     qinv.Conjugate();
00304 
00305     q = q*q2*qinv;
00306     return aiVector3t<TReal>(q.x,q.y,q.z);
00307 }
00308 
00309 #endif
00310 #endif // AI_QUATERNION_INL_INC
